#include <stdio.h>

struct Cat {
    char name[20];
    int fish;
};

int main(void) {
    struct Cat a;

    if (scanf("%s", a.name) != 1) {
        return 1;
    }
    if (scanf("%d", &a.fish) != 1) {
        return 1;
    }

    printf("%s 今天吃了 %d 条喵\n", a.name, a.fish);
    return 0;
}
